import UIKit

final class ProfileViewController: UIViewController {
    private let userID: String
    private let scrollView = UIScrollView(); private let stack = UIStackView()
    var onLogout: (() -> Void)?
    init(userID: String) { self.userID = userID; super.init(nibName: nil, bundle: nil) }
    @available(*, unavailable) required init?(coder: NSCoder) { fatalError("init(coder:) has not been implemented") }
    override func viewDidLoad() { super.viewDidLoad(); view.backgroundColor = WatchTheme.background; buildView() }
    private func buildView() {
        scrollView.translatesAutoresizingMaskIntoConstraints = false; view.addSubview(scrollView); NSLayoutConstraint.activate([scrollView.leadingAnchor.constraint(equalTo: view.leadingAnchor), scrollView.trailingAnchor.constraint(equalTo: view.trailingAnchor), scrollView.topAnchor.constraint(equalTo: view.topAnchor), scrollView.bottomAnchor.constraint(equalTo: view.bottomAnchor)])
        stack.translatesAutoresizingMaskIntoConstraints = false; stack.axis = .vertical; stack.spacing = 0; scrollView.addSubview(stack); NSLayoutConstraint.activate([stack.leadingAnchor.constraint(equalTo: scrollView.contentLayoutGuide.leadingAnchor, constant: 20), stack.trailingAnchor.constraint(equalTo: scrollView.contentLayoutGuide.trailingAnchor, constant: -20), stack.topAnchor.constraint(equalTo: scrollView.contentLayoutGuide.topAnchor, constant: 16), stack.bottomAnchor.constraint(equalTo: scrollView.contentLayoutGuide.bottomAnchor, constant: -24), stack.widthAnchor.constraint(equalTo: scrollView.frameLayoutGuide.widthAnchor, constant: -40)])
        stack.addArrangedSubview(WatchTheme.label("watch_profile", size: 24, weight: .bold)); stack.setCustomSpacing(8, after: stack.arrangedSubviews[0]); stack.addArrangedSubview(profileCard()); stack.setCustomSpacing(16, after: stack.arrangedSubviews[1]); stack.addArrangedSubview(settingsCard()); let logout = WatchTheme.button("watch_logout", color: WatchTheme.red); logout.heightAnchor.constraint(equalToConstant: 48).isActive = true; logout.addAction(UIAction { [weak self] _ in self?.onLogout?() }, for: .touchUpInside); stack.setCustomSpacing(16, after: stack.arrangedSubviews.last!); stack.addArrangedSubview(logout)
    }
    private func profileCard() -> UIView { let card = WatchTheme.gradientCard(); card.heightAnchor.constraint(equalToConstant: 136).isActive = true; let avatar = WatchTheme.avatar(textKey: WatchAvatarResolver.key(for: userID), color: UIColor.white.withAlphaComponent(0.35), size: 72); let texts = UIStackView(arrangedSubviews: [WatchTheme.label("watch_account_name", size: 20, weight: .bold, color: WatchTheme.surface), WatchTheme.label("watch_phone_number", size: 13, color: UIColor.white.withAlphaComponent(0.8))]); texts.axis = .vertical; texts.spacing = 7; let row = UIStackView(arrangedSubviews: [avatar, texts, WatchTheme.trailingChevronSlot(tint: WatchTheme.surface)]); row.translatesAutoresizingMaskIntoConstraints = false; row.axis = .horizontal; row.alignment = .center; row.spacing = 16; card.addSubview(row); NSLayoutConstraint.activate([row.leadingAnchor.constraint(equalTo: card.leadingAnchor, constant: 18), row.trailingAnchor.constraint(equalTo: card.trailingAnchor, constant: -18), row.centerYAnchor.constraint(equalTo: card.centerYAnchor)]); return card }
    private func settingsCard() -> UIView { let card = WatchTheme.card(); let rows = UIStackView(); rows.axis = .vertical; rows.spacing = 0; rows.translatesAutoresizingMaskIntoConstraints = false; card.addSubview(rows); NSLayoutConstraint.activate([rows.leadingAnchor.constraint(equalTo: card.leadingAnchor, constant: 14), rows.trailingAnchor.constraint(equalTo: card.trailingAnchor, constant: -14), rows.topAnchor.constraint(equalTo: card.topAnchor), rows.bottomAnchor.constraint(equalTo: card.bottomAnchor)]); rows.addArrangedSubview(settingRow(icon: .shield, key: "watch_account_security")); rows.addArrangedSubview(settingRow(icon: .bell, key: "watch_notifications")); rows.addArrangedSubview(settingRow(icon: .info, key: "watch_about")); return card }
    private func settingRow(icon: WatchIconKind, key: String) -> UIView { let row = UIStackView(arrangedSubviews: [WatchTheme.icon(icon, tint: WatchTheme.blue, size: 22), WatchTheme.label(key, size: 14), UIView(), WatchTheme.trailingChevronSlot()]); row.axis = .horizontal; row.alignment = .center; row.spacing = 12; row.heightAnchor.constraint(equalToConstant: 58).isActive = true; return row }
}
